SELECT join_id, challenge_id, member_id, member_phone, member_no, created_at
FROM volt_challenge_join
WHERE challenge_id = #{challengeId}
  AND member_phone = #{phone}
LIMIT 1

mapper.update:
UPDATE volt_challenge
SET joined_count = joined_count + 1
WHERE challenge_id = #{challengeId}
